-- Read one block of object IDs, model file IDs and names for this client.
local function AddObjects(rows)
	for id, file, name in rows:gmatch("(%d+) (%d+) ([^\n]*)\n") do
		AddObject(tonumber(id), tonumber(file), name ~= "" and name or nil)
	end
end

